def value_iteration(grid):
    def valid_move(x,y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])

    goal = 7

    # Initialize the reward table, where entry at (x,y) is the expected reward of reaching state (x,y)
    r = [[float('-inf') for _ in range(len(grid[0]))] for _ in range(len(grid))]

    # Initialize policy table
    policy = [["" for _ in range(len(grid[0]))] for _ in range(len(grid))]

    # Set initial reward of start state to 1 (assuming optimal path goes from start to goal)
    r[grid["start"]][grid["start"]] = 1

    # Define the four possible movements
    movements = [(0, -1), (0, 1), (-1, 0), (1, 0)]

    iterations = 0
    max_iterations = len(grid) * len(grid[0]) * 100
    while True:
        new_r = [[float('-inf') for _ in range(len(grid[0]))] for _ in range(len(grid))]

        # Update the reward table based on all possible actions from each state
        for x in range(len(grid)):
            for y in range(len(grid[0])):
                if grid[x][y] == "X":
                    continue

                v = 1 + r[x][y]
                for dx, dy in movements:
                    new_x, new_y = x + dx, y + dy
                    if valid_move(new_x,new_y) and grid[new_x][new_y] != "X" and (new_r[new_x][new_y] < v or (r[new_x][new_y] == float('-inf') and new_r[new_x][new_y] < 0)):
                        new_r[x][y] = max(new_r[x][y], v)
                        if r[new_x][new_y] != float('-inf'):
                            policy[x][y] = [(-dx, -dy)]

        # Check for convergence
        done = True
        for x in range(len(grid)):
            for y in range(len(grid[0])):
                if grid[x][y] == "X":
                    continue
                if new_r[x][y] != r[x][y]:
                    done = False

        iterations += 1
        if done or iterations > max_iterations:
            break

        # Update the reward table
        r = new_r

    states = []
    state_index = {}
    for x in range(len(grid)):
        for y in range(len(grid[0])):
            if grid[x][y] != "X":
                state_key = (x,y)
                policy_for_state = policy[state_index.get((x,y), len(states))]
                state_group_index = 0
                while policy_for_state[state_group_index]:
                    dx, dy = policy_for_state[state_group_index]
                    new_x, new_y = x + dx, y + dy
                    if (new_x,new_y) in state_index:
                        break
                    state_group_index += 1

                states.append([state_key for state_key in [(x,y), (x+dx,y+dy)]])
                state_index[(x,y)] = len(states) - 1

    # Merge equivalent states
    state_index = {}
    new_states = []
    while states:
        new_state = []
        for old_state_group in new_states:
            if states.index(old_state_group) == len(new_states)-1 or any((state_key not in [old_state[0] for old_state in old_state_group]) and (state_key != grid["goal"]) for state_key in old_state_group):
                continue
            new_state.extend(old_state_group)
        for old_state_group in states:
            if old_state_group == new_state:
                continue
            state_key = tuple(old_state_group[0])
            if state_key not in state_index:
                state_index[state_key] = len(new_states)
                new_states.append(old_state_group)

        if (new_state and new_state != states[-1]) or (not new_state and states.index(states[-1]) == len(new_states)-1):
            new_states.append(new_state)
        del states[states.index(new_state)]

    return new_states
